#include <functional>
#include <iostream>

void call(std::function<int()> f) // can be passed by value
{
    std::cout << f() << '\n';
}

int normal_function() { return 42; }

int main() {
    int n = 1;
    std::function<int()> f;
    try {
        call(f);
    } catch (const std::bad_function_call &ex) {
        std::cout << ex.what() << '\n';
    }

    f = [&n]() { return n; };
    call(f);

    n = 2;
    call(f);

    f = normal_function;
    call(f);

    std::function<void(std::string, int)> g;
    g = [](std::string str, int i) { std::cout << str << ' ' << i << '\n'; };
    g("Hi", 052);
}
